CREATE TABLE IF NOT EXISTS shipment(id VARCHAR(36) PRIMARY KEY,tenant_id VARCHAR(80) NOT NULL,user_id VARCHAR(80) NOT NULL,request_key VARCHAR(80) NOT NULL,origin VARCHAR(150) NOT NULL,destination VARCHAR(150) NOT NULL,cargo VARCHAR(100) NOT NULL,weight_kg BIGINT NOT NULL,distance_km BIGINT NOT NULL,fee_cents BIGINT NOT NULL,state VARCHAR(30) NOT NULL,state_version BIGINT NOT NULL DEFAULT 0,vehicle_id VARCHAR(36),signature VARCHAR(150),created_at BIGINT NOT NULL,UNIQUE(tenant_id,user_id,request_key));
CREATE TABLE IF NOT EXISTS outbox(id VARCHAR(36) PRIMARY KEY,tenant_id VARCHAR(80) NOT NULL,shipment_id VARCHAR(36) NOT NULL,target VARCHAR(30) NOT NULL,path VARCHAR(150) NOT NULL,payload CLOB NOT NULL,trace_id VARCHAR(80) NOT NULL,state VARCHAR(20) NOT NULL,attempts INT NOT NULL DEFAULT 0,next_at BIGINT NOT NULL,error VARCHAR(255));
